using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Sace.Api.Contracts;
using Sace.Api.Domain;
using Sace.Api.Infrastructure;
using Sace.Api.Services;
using Xunit;

namespace Sace.Api.Tests;

public class Sprint4CatalogTests {
  [Theory] [InlineData("8517.13.01","85171301",true)] [InlineData("85-01/10 10","85011010",true)] [InlineData("8501101","8501101",false)] [InlineData("ABC","ABC",false)]
  public void Tariff_normalization_and_validation_are_deterministic(string raw,string normalized,bool valid){Assert.Equal(normalized,RegulatoryCatalogRules.NormalizeTariff(raw));Assert.Equal(valid,RegulatoryCatalogRules.IsValidTariff(raw));}

  [Theory] [InlineData("01",true)] [InlineData("99",true)] [InlineData(null,true)] [InlineData("1",false)] [InlineData("A1",false)]
  public void Nico_is_validated_separately(string? nico,bool valid)=>Assert.Equal(valid,RegulatoryCatalogRules.IsValidNico(nico));

  [Fact] public async Task Dry_run_validates_without_writing_catalog_entities(){await using var f=await CatalogFixture.Create();var result=await f.Service.DryRunAsync(Package(),f.User.Id);Assert.True(result.CanImport);Assert.Equal(0,await f.Db.OfficialLegalSources.CountAsync());Assert.Equal(0,await f.Db.RegulatoryCatalogImports.CountAsync());Assert.Contains(await f.Db.SystemAuditLogs.ToListAsync(),x=>x.Action=="REGULATORY_CATALOG_DRY_RUN");}

  [Fact] public async Task Dry_run_rejects_unknown_citation_and_unverified_source(){await using var f=await CatalogFixture.Create();var package=Package() with{VerificationStatus=SourceVerificationStatus.REVIEWED,Requirements=[Requirement() with{CitationKeys=["MISSING"]}]};var result=await f.Service.DryRunAsync(package,f.User.Id);Assert.False(result.CanImport);Assert.Contains(result.Errors,x=>x.Code=="SOURCE_NOT_VERIFIED");Assert.Contains(result.Errors,x=>x.Code=="UNKNOWN_CITATION");Assert.Empty(await f.Db.OfficialLegalSources.ToListAsync());}

  [Fact] public async Task Import_is_atomic_persisted_and_duplicate_hash_is_idempotent(){await using var f=await CatalogFixture.Create();var package=Package();var imported=await f.Service.ImportAsync(package,f.User.Id);Assert.True(imported.CanImport);Assert.NotNull(imported.ImportId);Assert.Equal(1,await f.Db.OfficialLegalSources.CountAsync());Assert.Equal(1,await f.Db.RegulatoryRequirements.CountAsync());Assert.Equal(1,await f.Db.RegulatoryTariffEntries.CountAsync());var duplicate=await f.Service.ImportAsync(package,f.User.Id);Assert.True(duplicate.AlreadyImported);Assert.Equal(1,await f.Db.RegulatoryCatalogImports.CountAsync());Assert.Equal(1,await f.Db.RegulatoryRequirements.CountAsync());}

  [Fact] public async Task Qualified_tariff_match_requires_manual_review_without_material_data(){await using var f=await RegulatoryFixture.Create(tariff:"8517.13.01",date:new(2026,12,1));var source=new OfficialLegalSource{Code="TEST-DOF",Title="Test",SourceType=OfficialSourceType.DOF_PUBLICATION,Authority="Test",OfficialUrl="https://dof.gob.mx/test",Status=SourceVerificationStatus.VERIFIED};var version=new OfficialLegalSourceVersion{OfficialLegalSource=source,VersionLabel="v1",PublicationDate=new(2026,9,1),EffectiveFrom=new(2026,9,2),OfficialUrl=source.OfficialUrl,VerificationStatus=SourceVerificationStatus.VERIFIED};var citation=new OfficialSourceCitation{OfficialLegalSourceVersion=version,CitationType=OfficialCitationType.ANNEX,CitationLabel="Anexo"};var rule=new RegulatoryRequirement{Code="REAL-Q",Version=1,Name="Qualified",RequirementCategory=RequirementCategory.NOM,OperationScope=RegulatoryOperationScope.IMPORT,Status=RegulatoryRequirementStatus.VERIFIED,EffectiveFrom=new(2026,9,2),SourceCitations=[new(){OfficialSourceCitation=citation}],TariffEntries=[new(){RawTariffFraction="8517.13.01",NormalizedTariffFraction="85171301",OperationScope=RegulatoryOperationScope.IMPORT,QualificationType=QualificationType.ONLY_IF,QualificationText="Únicamente mercancía con alcance técnico específico.",EffectiveFrom=new(2026,9,2),OfficialSourceCitation=citation,Status=SourceVerificationStatus.VERIFIED}]};f.Db.Add(rule);await f.Save();var result=Assert.Single(await f.Evaluate());Assert.Equal(RegulatoryApplicabilityOutcome.MANUAL_REVIEW,result.AutomatedOutcome);Assert.Contains("Acotación oficial",result.Explanation);}

  [Fact] public async Task Unqualified_verified_tariff_match_can_apply_and_preserve_legal_separation(){await using var f=await RegulatoryFixture.Create(tariff:"8501.10.10",nico:"06",date:new(2026,10,1));var citation=Citation();var rule=new RegulatoryRequirement{Code="REAL-A",Version=1,Name="Applicable",RequirementCategory=RequirementCategory.NOM,OperationScope=RegulatoryOperationScope.IMPORT,Status=RegulatoryRequirementStatus.VERIFIED,EffectiveFrom=new(2026,9,1),SourceCitations=[new(){OfficialSourceCitation=citation}],TariffEntries=[new(){RawTariffFraction="8501.10.10",NormalizedTariffFraction="85011010",Nico="06",OperationScope=RegulatoryOperationScope.IMPORT,QualificationType=QualificationType.NONE,EffectiveFrom=new(2026,9,1),OfficialSourceCitation=citation,Status=SourceVerificationStatus.VERIFIED}]};f.Db.Add(rule);await f.Save();var result=Assert.Single(await f.Evaluate());Assert.Equal(RegulatoryApplicabilityOutcome.APPLIES,result.AutomatedOutcome);Assert.Contains("Resultado LEGAL: No evaluado",result.Explanation);Assert.Empty(await f.Db.Findings.ToListAsync());}

  static OfficialSourceCitation Citation(){var source=new OfficialLegalSource{Code=$"SRC-{Guid.NewGuid():N}",Title="Official",SourceType=OfficialSourceType.DOF_PUBLICATION,Authority="Authority",OfficialUrl="https://dof.gob.mx/test",Status=SourceVerificationStatus.VERIFIED};var version=new OfficialLegalSourceVersion{OfficialLegalSource=source,VersionLabel="v1",PublicationDate=new(2026,9,1),EffectiveFrom=new(2026,9,2),OfficialUrl=source.OfficialUrl,VerificationStatus=SourceVerificationStatus.VERIFIED};return new(){OfficialLegalSourceVersion=version,CitationType=OfficialCitationType.ANNEX,CitationLabel="Anexo"};}
  static RegulatoryCatalogPackage Package()=>new(1,"TEST-PACKAGE-1","TEST-SOURCE","Fuente oficial de prueba",OfficialSourceType.DOF_PUBLICATION,"Autoridad de prueba","https://dof.gob.mx/test","v1",null,new(2026,9,1,0,0,0,DateTimeKind.Utc),new(2026,9,2,0,0,0,DateTimeKind.Utc),null,SourceVerificationStatus.VERIFIED,[new("C1",OfficialCitationType.ANNEX,"Anexo de prueba")],[Requirement()]);
  static CatalogRequirementItem Requirement()=>new("TEST-REQ","Regla de prueba",null,RequirementCategory.NOM,RegulatoryAuthorityCode.ECONOMIA,null,RegulatoryOperationScope.IMPORT,"Anexo",new(2026,9,2,0,0,0,DateTimeKind.Utc),null,true,false,["C1"],[new("8501.10.10","06",RegulatoryOperationScope.IMPORT,null,null,QualificationType.NONE,null,null,null,new(2026,9,2,0,0,0,DateTimeKind.Utc),null,"C1")],[],[]);
}

public class Sprint4ApiAndSeedTests {
  [Theory] [InlineData("GET","/api/legal-sources")] [InlineData("GET","/api/legal-sources/00000000-0000-0000-0000-000000000001")] [InlineData("POST","/api/legal-sources")] [InlineData("POST","/api/legal-sources/00000000-0000-0000-0000-000000000001/versions")] [InlineData("POST","/api/legal-sources/00000000-0000-0000-0000-000000000001/verify")] [InlineData("GET","/api/legal-sources/00000000-0000-0000-0000-000000000001/diff")] [InlineData("POST","/api/regulatory-catalog/import/dry-run")] [InlineData("POST","/api/regulatory-catalog/import")] [InlineData("GET","/api/regulatory-catalog/imports")]
  public async Task Sprint4_endpoints_require_jwt(string method,string path){using var factory=new SaceFactory();var response=await factory.CreateClient().SendAsync(new HttpRequestMessage(new HttpMethod(method),path));Assert.Equal(HttpStatusCode.Unauthorized,response.StatusCode);}

  [Fact] public async Task Seed_contains_exactly_two_initial_verified_real_rules_with_verified_citations(){using var factory=new SaceFactory();var client=await Authenticated(factory);var response=await client.GetAsync("/api/regulatory-requirements?status=VERIFIED");response.EnsureSuccessStatusCode();using var json=JsonDocument.Parse(await response.Content.ReadAsStringAsync());var real=json.RootElement.EnumerateArray().Where(x=>x.GetProperty("code").GetString()!.StartsWith("RRNA-NOM-")).ToList();Assert.Equal(2,real.Count);Assert.All(real,x=>Assert.Equal("VERIFIED",x.GetProperty("sourceCitations")[0].GetProperty("officialSourceCitation").GetProperty("officialLegalSourceVersion").GetProperty("verificationStatus").GetString()));}

  [Fact] public async Task Legal_source_admin_workflow_creates_staged_version_and_verifies_it(){using var factory=new SaceFactory();var client=await Authenticated(factory);var code=$"TEST-SRC-{Guid.NewGuid():N}";var created=await client.PostAsJsonAsync("/api/legal-sources",new{code,title="Fuente de prueba",sourceType="DOF_PUBLICATION",authority="Autoridad",officialUrl="https://dof.gob.mx/test"});Assert.Equal(HttpStatusCode.Created,created.StatusCode);using var sourceJson=JsonDocument.Parse(await created.Content.ReadAsStringAsync());var id=sourceJson.RootElement.GetProperty("id").GetGuid();var version=await client.PostAsJsonAsync($"/api/legal-sources/{id}/versions",new{versionLabel="v1",dofPublicationCode=(string?)null,publicationDate="2026-01-01T00:00:00Z",effectiveFrom="2026-01-02T00:00:00Z",effectiveTo=(string?)null,officialUrl="https://dof.gob.mx/test",sha256=(string?)null,verificationNotes="Prueba",citations=new[]{new{citationType="ARTICLE",citationLabel="Artículo 1"}}});Assert.Equal(HttpStatusCode.Created,version.StatusCode);using var versionJson=JsonDocument.Parse(await version.Content.ReadAsStringAsync());var verified=await client.PostAsJsonAsync($"/api/legal-sources/{id}/verify",new{versionId=versionJson.RootElement.GetProperty("id").GetGuid(),verificationNotes="Cotejada"});Assert.True(verified.IsSuccessStatusCode,await verified.Content.ReadAsStringAsync());Assert.Contains("VERIFIED",await verified.Content.ReadAsStringAsync());}

  static async Task<HttpClient> Authenticated(SaceFactory factory){var client=factory.CreateClient();var login=await client.PostAsJsonAsync("/api/auth/login",new{email="admin@sace.local",password="Admin123!"});login.EnsureSuccessStatusCode();using var json=JsonDocument.Parse(await login.Content.ReadAsStringAsync());client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",json.RootElement.GetProperty("token").GetString());return client;}
}

sealed class CatalogFixture:IAsyncDisposable {
  readonly SqliteConnection connection;public SaceDbContext Db{get;}public User User{get;}public RegulatoryCatalogImportService Service{get;}
  CatalogFixture(SqliteConnection c,SaceDbContext db,User user){connection=c;Db=db;User=user;Service=new(db);}
  public static async Task<CatalogFixture>Create(){var c=new SqliteConnection("DataSource=:memory:");await c.OpenAsync();var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite(c).Options);await db.Database.EnsureCreatedAsync();var user=new User{Name="Governance",Email=$"{Guid.NewGuid():N}@example.invalid",PasswordHash="x"};db.Users.Add(user);await db.SaveChangesAsync();return new(c,db,user);}
  public async ValueTask DisposeAsync(){await Db.DisposeAsync();await connection.DisposeAsync();}
}
